  if (!text || typeof text !== 'string') return null;
  const nounAlt    = PILL_NOUNS.join('|');
  const effectsAlt = DESCRIPTOR_EFFECTS.join('|');
  const bodyAlt    = BODY_MODIFIERS.join('|');
