    '\\b(pink|blue|purple)\\b' +
    '\\s+(?:(?:' + bodyAlt + ')\\s+)?' +
    '(?:(?:' + effectsAlt + ')\\s+){0,4}' +
    '\\b(?:' + nounAlt + ')\\b';
