    '\\b(red|green)\\b' +
    '\\s+(?:(?:' + bodyAlt + ')\\s+)?' +
    '(?:(?:' + effectsAlt + ')\\s+){0,4}' +
    '\\b(?:' + nounAlt + ')\\b';
  const re = new RegExp('(?:' + branchA + ')|(?:' + branchB + ')', 'i');
  const m = re.exec(text);
  if (!m) return null;
