const MASC_KEYWORDS = {"masculine_physical":{"words":["chiseled","scarred","rugged","muscular","broad-shouldered","hairy","stubble","beard","grizzled","barrel-chested","calloused","thick-necked"],"delta":3,"cap":3},"masculine_identity":{"words":["masculine","manly","alpha male","macho","virile","man's man","red-blooded"],"delta":4,"cap":2},"masculine_role":{"words":["dad","father","husband","patriarch"],"delta":3,"cap":2},"feminine_body_on_male":{"words":["feminine curves","hourglass","wide hips","perky chest","soft features","pretty face","pouty lips","smooth hairless","plush thighs","bubble butt","bouncy chest","feminine figure"],"delta":-4,"cap":3},"feminine_identity":{"words":["femboy","feminine cravings","girl mode","felt female","always been a girl","sissy","crossdress","en femme","bimbo"],"delta":-5,"cap":2},"trans_medical":{"words":["hormones","hrt","estrogen","testosterone","top surgery","bottom surgery","chest binding","hormone-grown","fat redistribution"],"delta":-6,"cap":2},"trans_identity":{"words":["trans woman","trans man","male frame softened","cis woman","cis man"],"delta":-4,"cap":2},"feminine_physical_mild":{"words":["delicate","dainty","soft skin","slender","graceful build","androgynous","petite frame"],"delta":-2,"cap":2}};

function _generateInitialMasculinity(cardText, birthSex, stats, tags) {
  // male = born male, full masculine baseline
  // female = born female, full feminine baseline
  // trans_female = MTF = already transitioned, start at midpoint
  // trans_male = FTM = already transitioned, start at midpoint
  // v7.7.26 — tag-aware archetype baselines: a card tagged 'femboy' / 'sissy' /
  // 'crossdresser' is identifying its archetype directly. The previous
  // description-only scan missed these because Marco's card (tag 'femboy') had
  // no literal 'femboy' word in the description text → ended up at 93 instead
  // of ~63. Tags win over the birthSex default; keyword scan still tunes from
  // there. For femboy archetypes we additionally tilt by orientation (gay → fem)
  // and DOM stat (high DOM → masc, low DOM → fem) since those modify
  // presentation within the archetype.
  var tagList = (tags || []).map(function(t){ return String(t).toLowerCase().trim(); });
  var tagSet = new Set(tagList);
  // v7.7.27 — substring match on tags so compound archetype tags ("closeted
  // femboy", "shy sissy", "amateur crossdresser") still trigger the right
  // archetype baseline. Exact-match was too strict and missed Jean's
  // 'closeted femboy' tag, leaving her at 93 instead of ~57. Also scan the
  // card description text as a fallback for cards with sparse tags.
  var archetypeBaseline = null;
  var archetypeName = null;
  var _hasArchTag = function(needle) {
    for (var i = 0; i < tagList.length; i++) {
      if (tagList[i].indexOf(needle) >= 0) return true;
    }
    return false;
  };
  var _descLower = (cardText || '').toLowerCase();
  var _hasArchDesc = function(needle) {
    return new RegExp('\\b' + needle + '\\b').test(_descLower);
  };
  if (_hasArchTag('femboy') || _hasArchDesc('femboy'))            { archetypeBaseline = 65; archetypeName = 'femboy'; }
  else if (_hasArchTag('sissy') || _hasArchDesc('sissy'))         { archetypeBaseline = 45; archetypeName = 'sissy'; }
  else if (_hasArchTag('crossdresser') || _hasArchTag('en femme')
        || _hasArchDesc('crossdresser') || _hasArchDesc('en femme')) { archetypeBaseline = 55; archetypeName = 'crossdresser'; }

  var baseline;
  if (archetypeBaseline !== null) baseline = archetypeBaseline;
  else if (birthSex === 'male') baseline = 95;
  else if (birthSex === 'female') baseline = 5;
  else if (birthSex === 'trans_female' || birthSex === 'trans_male') baseline = 50;
  else baseline = 50;

  // v7.7.26 — tag-driven modifiers. Only stack onto archetype baselines so we
  // don't accidentally pull a regular cis-male card down for being 'gay'.
  var tagDelta = 0;
  var tagApplied = [];
  if (archetypeBaseline !== null) {
    if (tagSet.has('gay'))      { tagDelta -= 5; tagApplied.push('gay:-5'); }
    if (tagSet.has('bisexual')) { tagDelta -= 2; tagApplied.push('bi:-2'); }
    var dom = parseInt((stats || {}).DOM || 10, 10);
    if (dom >= 14)     { tagDelta += 5; tagApplied.push('high_DOM:+5'); }
    else if (dom <= 8) { tagDelta -= 3; tagApplied.push('sub_DOM:-3'); }
  }

  const combined = (cardText || '').toLowerCase();

  // Keywords still apply on top — personality stats (DOM/SUB) are not gender
  // identity globally; the DOM tilt above is archetype-scoped only.
  let kwDelta = 0;
  for (const [_cat, cfg] of Object.entries(MASC_KEYWORDS || {})) {
    let hits = 0;
    for (const kw of cfg.words || []) {
      if (new RegExp('\\b' + reEscape(kw) + '\\b').test(combined)) {
        hits++;
        if (hits >= cfg.cap) break;
      }
    }
    kwDelta += hits * cfg.delta;
  }

  const result = Math.max(0, Math.min(100, baseline + tagDelta + kwDelta));

  console.log('[MASC] Initial masculinity=' + result
    + ' (baseline=' + baseline
    + (archetypeName ? ' archetype=' + archetypeName : '')
    + (tagApplied.length ? ' tags=[' + tagApplied.join(',') + ']' : '')
    + ' kw_delta=' + kwDelta
    + ' sex=' + birthSex + ')');

  return result;
}

function _snapshotMasculinityResist(state) {
  const domMod = _fragStatMod(parseInt((state.stats || {}).DOM || 10, 10)
    + ((state._perm_stat_mods || {}).DOM || 0));
  const wisMod = _fragStatMod(parseInt((state.stats || {}).WIS || 10, 10)
    + ((state._perm_stat_mods || {}).WIS || 0));
  const resist = domMod + wisMod;
  state._masc_resist_mod = resist;
  console.log('[MASC] resist snapshot: DOM_mod=' + domMod
    + ' WIS_mod=' + wisMod + ' → resist=' + resist);
  return resist;
}

function _masculinityBand(mascValue) {
  const v = Math.max(0, Math.min(100, parseInt(mascValue, 10)));
  if (v === 0) return 0;
  return Math.min(10, Math.floor((v - 1) / 10) + 1);
}

function _masculinityBandName(mascValue) {
  return (_MASCULINITY_BAND_NAMES || {})[_masculinityBand(mascValue)] || 'unknown';
}

function _masculinityBandLabel(mascValue) {
  return (_MASCULINITY_BAND_LABELS || {})[_masculinityBand(mascValue)] || 'Unknown';
}

// v7.18.0 — IDENTITY takes over for masculinity (Cody 2026-09-15: "identity takes over for
// masculinity so the work is saved just scaling and such is redone"). identity = how much of
// the ORIGIN self remains: 100 = original identity intact, 0 = fully flipped into the other
// gender — the game's identity slider, origin-relative, so one glance says how far gone any
// character is regardless of origin. The proven internals (d20 gate walk, pill deltas, band
// tables, origin ladder, zone brackets) keep operating on the absolute masculine<->feminine
// axis; state.masculinity stays as that internal working value, mirror-synced from/to
// identity through origin polarity so no reader breaks and no authored table moves.
function _originPolarity(state) {
  // +1 = origin self sits at the masculine pole (identity == masc);
  // -1 = origin self sits at the feminine pole (identity == 100 - masc).
  // intersex: masculine-pole placeholder — parked with purple for Cody's call.
  const o = (state && state._sex_origin) || 'male';
  return (o === 'female' || o === 'trans_female') ? -1 : 1;
}
function _identMascConvert(state, v) {
  // identity->masc and masc->identity are the same involution per polarity.
  const n = Math.max(0, Math.min(100, parseInt(v, 10) || 0));
  return _originPolarity(state) > 0 ? n : 100 - n;
}
function _identityWord(ident) {
  const v = Math.max(0, Math.min(100, parseInt(ident, 10) || 0));
  if (v >= 85) return 'intact';
  if (v >= 65) return 'holding';
  if (v >= 45) return 'slipping';
  if (v >= 25) return 'fracturing';
  if (v >= 5) return 'fallen';
  return 'flipped';
}
function _syncIdentity(state, phase) {
  // Keeps state.identity (canonical, origin-relative) and state.masculinity (internal
  // absolute mirror) in agreement. phase 'load': an externally edited identity (manual
  // state edit, import) wins and re-seats masculinity; otherwise masculinity (the value
  // the machinery moves) is truth and identity is recomputed from it.
  if (!state) return;
  const m = state.masculinity, id = state.identity;
  if (m == null && id == null) return;
  if (m == null) {
    state.masculinity = _identMascConvert(state, id);
  } else if (phase === 'load' && id != null && id !== state._ident_last
             && id !== _identMascConvert(state, m)) {
    state.masculinity = _identMascConvert(state, id);
  }
  state.identity = _identMascConvert(state, state.masculinity);
  state._ident_last = state.identity;
}

function _nextMascBoundary(current, delta) {
  if (delta === 0) return null;
  const target = Math.max(0, Math.min(100, current + delta));
  const curBand = _masculinityBand(current);
  const tgtBand = _masculinityBand(target);
  if (curBand === tgtBand) return null;

  if (delta < 0) {
    return (curBand - 1) * 10;
  } else {
    return curBand * 10 + 1;
  }
}

function _applyMasculinityDelta(state, delta) {
  if (delta === 0) return;

  // v7.12.0 stat-gain: scale the swing MAGNITUDE (high SUB / low DOM feminizes faster).
  // Sign preserved; gates (DOM+WIS band rolls below) untouched.
  delta = Math.round(delta * _statGainFactor(state, 'masculinity'));
  if (delta === 0) return;

  const current = parseInt(state.masculinity != null ? state.masculinity : 50, 10);
  const target = Math.max(0, Math.min(100, current + delta));
  if (target === current) return;

  const resistMod = parseInt(state._masc_resist_mod || 0, 10);
  const movingDown = delta < 0;
  let pos = current;

  while (true) {
    const remaining = target - pos;
    if (remaining === 0) break;

    const boundary = _nextMascBoundary(pos, remaining);
    if (boundary === null) {
      pos = target;
      break;
    }

    const dc = parseInt(state._masc_gate_dc || 5, 10);
    const roll = randInt(1, 20);
    const total = roll + resistMod;
    const passed = total >= dc;

    const b = _masculinityBand(pos);
    const resultStr = passed ? 'RESIST' : 'FAIL';
    const entry = 'MASC GATE @' + boundary + ': d20(' + roll + ')+'
      + resistMod + '=' + total + ' vs DC' + dc
      + ' [band' + b + '] ' + resultStr
      + ' (target=' + target + ')';
    (state._notes_log = state._notes_log || []).push(entry);
    console.log('[MASC] ' + entry);

    if (passed) {
      const heldAt = movingDown ? boundary + 1 : boundary - 1;
      pos = Math.max(0, Math.min(100, heldAt));
      state._masc_gate_dc = dc + 1;
      break;
    } else {
      pos = boundary;
      state._masc_gate_dc = dc + 2;
      state._masc_gate_fail_count = (state._masc_gate_fail_count || 0) + 1;
      _bimboAdvanceCheck(state);
    }
  }

  if (pos === current) return;

  const actualDelta = pos - current;
  state.masculinity = pos;
  _syncIdentity(state);
  state._masculinity_delta_this_session = (parseInt(state._masculinity_delta_this_session || 0, 10) + actualDelta);

  const oldBand = _masculinityBandName(current);
  const newBand = _masculinityBandName(pos);
  const bandShift = (oldBand === newBand) ? '' : ' BAND:' + oldBand + '->' + newBand;
  const entry2 = 'masculinity:' + current + '->' + pos
    + ' (delta=' + actualDelta + ')' + bandShift;
  (state._notes_log = state._notes_log || []).push(entry2);
  console.log('[MASC] ' + entry2);

  state._masc_shifted_this_turn = true;
}

// ──────────────────────────────────────────────────────────────────────────────
// EFFECT RESISTANCE SYSTEM — boundary-gated d20 walk (mirrors masculinity)
// ──────────────────────────────────────────────────────────────────────────────

// 11 bands (0-10), same structure as masculinity.
// resistance 0 = rewritten, resistance 100 = untouched
function _effectResistanceBand(resistance) {
  if (resistance <= 0) return 0;
  return Math.min(10, Math.ceil(resistance / 10));
}

const _EFFECT_RESIST_BAND_NAMES = {
  10: 'untouched', 9: 'fortified', 8: 'guarded', 7: 'tested',
  6: 'contested', 5: 'losing', 4: 'yielding', 3: 'fading',
  2: 'eroded', 1: 'conditioned', 0: 'rewritten',
};

const _EFFECT_RESIST_BAND_LABELS = {
  10: 'Untouched', 9: 'Fortified', 8: 'Guarded', 7: 'Tested',
  6: 'Contested', 5: 'Losing', 4: 'Yielding', 3: 'Fading',
  2: 'Eroded', 1: 'Conditioned', 0: 'Rewritten',
};

function _effectResistanceBandName(resistance) {
  return _EFFECT_RESIST_BAND_NAMES[_effectResistanceBand(resistance)] || 'unknown';
}

// Per-effect stat pairs for resist modifier
const _EFFECT_RESIST_STATS = {
  submissive: ['DOM', 'WIS'],
  compliant:  ['WIS', 'INT'],
  breeder:    ['CON', 'WIS'],
  bimbo:      ['INT', 'WIS'],
  bull:       ['DOM', 'CON'],
  denial:     ['WIS', 'CON'],
};

// Per-effect DC counter-stat. The named stat_mod is ADDED to the applied ROLL2 DC,
// making high-counter chars more susceptible. Chosen so counter-stat is NOT in the
// effect's resist pair (avoids self-cancellation with resistMod).
const _EFFECT_DC_COUNTER_STAT = {
  bimbo:      'CHA_mod',  // glamour/attention susceptibility
  breeder:    'SUB_mod',  // instinct to yield to breeding urge
  submissive: 'SUB_mod',  // pre-existing sub inclination
  compliant:  'CHA_mod',  // attracts directives/authority
  bull:       'CHA_mod',  // sexual magnetism pulls the dom urge
  denial:     'SUB_mod',  // sub chars crave release harder
};

// Arousal-band bonus injected into ROLL1 trigger chance. Band keys match _EFFECT_RESIST_DROP.
const _ROLL1_AROUSAL_PRESSURE = {
  cold: 0, warm: 3, build: 8, heat: 12, intense: 18, over: 24, edge: 30,
};

// ROLL1 total trigger-chance cap. Prevents peak arousal from feeling inevitable.
const _ROLL1_CAP = 60;

// ROLL2 applied-DC cap after A+B+C stack.
const _ROLL2_DC_CAP = 22;

// Per-effect trigger events (keys from detectEvents)
const _EFFECT_RESIST_TRIGGERS = {
  submissive: ['directive', 'orgasm', 'penetration_attempt'],
  compliant:  ['directive', 'orgasm'],
  breeder:    ['creampie_vaginal', 'orgasm_denied', 'arousal_spike_60'],
  bimbo:      ['orgasm', 'arousal_spike_50'],
  bull:       ['orgasm', 'arousal_spike_50'],
  denial:     ['orgasm_denied', 'arousal_spike_70'],
};

// Drop amount per gate fail, scaled by arousal band
const _EFFECT_RESIST_DROP = {
  cold: -2, warm: -3, build: -4, heat: -5,
  intense: -7, over: -9, edge: -12,
};

// Arousal → band name for drop lookup
function _arousalDropBand(arousal) {
  if (arousal < 15) return 'cold';
  if (arousal < 30) return 'warm';
  if (arousal < 45) return 'build';
  if (arousal < 60) return 'heat';
  if (arousal < 75) return 'intense';
  if (arousal < 90) return 'over';
  return 'edge';
}

// Compute resist modifier from effect's stat pair
function _snapshotEffectResistMod(state, effect) {
  var statPair = _EFFECT_RESIST_STATS[effect];
  if (!statPair) return 0;
  var stats = state.stats || {};
  var total = 0;
  for (var i = 0; i < statPair.length; i++) {
    var val = parseInt(stats[statPair[i]] || 10, 10);
    total += Math.floor((val - 10) / 2);
  }
  return total;
}

// Lazy init resistance for an effect
function _initEffectResistance(state, effect) {
  state.effect_resistance = state.effect_resistance || {};
  state._effect_resist_dc = state._effect_resist_dc || {};
  if (state.effect_resistance[effect] == null) {
    state.effect_resistance[effect] = 100;
  }
  if (state._effect_resist_dc[effect] == null) {
    state._effect_resist_dc[effect] = 10;
  }
}

// Find next band boundary in direction of delta (mirrors _nextMascBoundary)
function _nextResistBoundary(current, delta) {
  if (delta === 0) return current;
  var band = _effectResistanceBand(current);
  if (delta < 0) {
    var boundary = band * 10;
    if (current <= boundary) {
      boundary = (band - 1) * 10;
    }
    return Math.max(0, boundary);
  } else {
    var upper = (band + 1) * 10 + 1;
    if (current >= upper) upper = (band + 2) * 10 + 1;
    return Math.min(100, upper);
  }
}

// Breeder drive ramps with arousal, capped by deepest resistance ever reached.
// At cold arousal the character reads as untouched regardless of stored R; as
// arousal rises, effective R collapses toward the low-water mark. NARRATIVE ONLY —
// stored R, ROLL1 trigger, and ROLL2 DC are unchanged. Low-water lazy-updates
// from current R on every read, so any path that drops breeder R is captured
// without hooking each write site.
function _breederEffectiveResistance(state) {
  _initEffectResistance(state, 'breeder');
  var currentR = (state.effect_resistance && state.effect_resistance.breeder != null)
    ? state.effect_resistance.breeder : 100;
  state.flags = state.flags || {};
  var lowWater = (typeof state.flags._breeder_low_water === 'number')
    ? state.flags._breeder_low_water : 100;
  if (currentR < lowWater) lowWater = currentR;
  state.flags._breeder_low_water = lowWater;
  // Trip permanent broken flag when low-water crosses into eroded band — recovery cap engages.
  if (lowWater <= 20 && !state.flags._breeder_broken) {
    state.flags._breeder_broken = true;
    var _brkEntry = 'breeder:BROKEN at lowWater=' + lowWater + ' (recovery cap engaged)';
    (state.roll_log = state.roll_log || []).push(_brkEntry);
    console.log('[RESIST] ' + _brkEntry);
  }
  var arBand = _arousalDropBand(parseInt(state.arousal || 0, 10));
  var pressure = _ROLL1_AROUSAL_PRESSURE[arBand] || 0;
  var arousalFactor = pressure / 30;
  var effR = Math.round(100 - (100 - lowWater) * arousalFactor);
  if (effR < 0) effR = 0;
  if (effR > 100) effR = 100;
  return effR;
}

// Boundary-gated walk — moves resistance toward target, d20 gate at each band boundary
function _applyEffectResistanceDelta(state, effect, delta) {
  // Post-birth axe — surrogate's revert-turn d100>60 pass removes breeder from play entirely
  if (effect === 'breeder' && state.flags && state.flags._breeder_axed) return;
  _initEffectResistance(state, effect);
  var current = state.effect_resistance[effect];
  var target = Math.max(0, Math.min(100, current + delta));

  if (target === current) return;

  var pos = current;
  var steps = 0;
  var maxSteps = 20;

  while (pos !== target && steps < maxSteps) {
    steps++;
    var boundary = _nextResistBoundary(pos, delta < 0 ? -1 : 1);

    // If no boundary between pos and target, slide freely
    if ((delta < 0 && boundary <= target) || (delta > 0 && boundary >= target)) {
      pos = target;
      break;
    }

    // Arrived at boundary — gate with d20
    pos = boundary;
    var dc = parseInt(state._effect_resist_dc[effect] || 10, 10);
    var resistMod = _snapshotEffectResistMod(state, effect);
    var d20 = Math.floor(Math.random() * 20) + 1;
    var total = d20 + resistMod;

    if (total >= dc) {
      // Held — stop just before boundary
      if (delta < 0) pos = boundary + 1;
      else pos = boundary - 1;
      state._effect_resist_dc[effect] = dc + 1;
      var passEntry = effect + '_resist:GATE_HOLD(d20=' + d20 + (resistMod >= 0 ? '+' : '') + resistMod + '=' + total + ' vs DC=' + dc + ') held@' + pos;
      (state.roll_log = state.roll_log || []).push(passEntry);
      console.log('[RESIST] ' + passEntry);
      break;
    } else {
      // Broke through — cross boundary, DC escalates faster on fails
      if (delta < 0) pos = boundary - 1;
      else pos = boundary + 1;
      state._effect_resist_dc[effect] = dc + 2;
      if (!state._effect_resist_fail_count || typeof state._effect_resist_fail_count !== 'object') state._effect_resist_fail_count = {};
      state._effect_resist_fail_count[effect] = (state._effect_resist_fail_count[effect] || 0) + 1;
      var failEntry = effect + '_resist:GATE_BREAK(d20=' + d20 + (resistMod >= 0 ? '+' : '') + resistMod + '=' + total + ' vs DC=' + dc + ') crossed→' + pos;
      (state.roll_log = state.roll_log || []).push(failEntry);
      console.log('[RESIST] ' + failEntry);
    }
  }

  pos = Math.max(0, Math.min(100, pos));
  // Breeder broken floor — once lowWater ≤ 20, recovery (positive delta) is sealed at lowWater.
  // Erosion still flows freely; she can keep falling, never grind back above her low-water mark.
  if (effect === 'breeder' && delta > 0 && state.flags && state.flags._breeder_broken) {
    var _lwCap = (typeof state.flags._breeder_low_water === 'number') ? state.flags._breeder_low_water : 100;
    if (pos > _lwCap) pos = _lwCap;
  }
  state.effect_resistance[effect] = pos;

  var newBand = _effectResistanceBand(pos);
  var oldBand = _effectResistanceBand(current);
  if (newBand !== oldBand) {
    console.log('[RESIST] ' + effect + ' band shift: ' + _EFFECT_RESIST_BAND_NAMES[oldBand] + ' → ' + _EFFECT_RESIST_BAND_NAMES[newBand] + ' (resistance=' + pos + ')');
    (state._notes_log = state._notes_log || []).push('resist_' + effect + ':' + _EFFECT_RESIST_BAND_NAMES[oldBand] + '→' + _EFFECT_RESIST_BAND_NAMES[newBand]);
  }
}

// Reset DCs and fail counts per session (resistance value persists, DCs don't)
function _resetEffectResistDCs(state) {
  var dcs = state._effect_resist_dc || {};
  for (var eff in dcs) {
    dcs[eff] = 10;
  }
  state._effect_resist_dc = dcs;
  var fails = state._effect_resist_fail_count || {};
  for (var eff in fails) {
    fails[eff] = 0;
  }
  state._effect_resist_fail_count = fails;
}

// Process resistance for all active effects — called from processEvents
// Two-roll system (mirrors bimbo advance):
//   Roll 1 — d100 vs pressure chance (more fails = more likely to fire)
//   Roll 2 — d20 + stat mods vs DC (determines if resistance actually drops)
// If both fail, the arousal-scaled delta feeds into the boundary walk.
function _processEffectResistance(state, events, rs) {
  var effects = state.active_effects || [];
  var arousal = parseInt(state.arousal || 0, 10);
  var dropBand = _arousalDropBand(arousal);
  var dropAmount = _EFFECT_RESIST_DROP[dropBand] || -2;
  var _processed = {};

  for (var i = 0; i < effects.length; i++) {
    var eff = effects[i];
    // Surrogate piggybacks on breeder's resistance, triggers, stats, and DCs
    if (eff === 'surrogate') eff = 'breeder';
    // Dedupe — skip if we've already processed this resistance key this turn
    if (_processed[eff]) continue;
    _processed[eff] = true;

    var triggers = _EFFECT_RESIST_TRIGGERS[eff];
    if (!triggers) continue;
    // Post-birth axe — surrogate's revert-turn d100>60 pass removes breeder from play entirely
    if (eff === 'breeder' && state.flags && state.flags._breeder_axed) continue;
    // Motherhood mode — breeder resistance paused once motherhood begins (post-conception turn).
    // Also paused on surrogate snapshot path (preserves legacy surrogate ramp logic).
    if (eff === 'breeder' && state.flags && (state.flags._preconception_breeder_resistance != null || _isMotherhoodMode(state))) continue;

    _initEffectResistance(state, eff);

    // Check if any trigger event fired this turn
    var fired = false;
    for (var t = 0; t < triggers.length; t++) {
      var trigKey = triggers[t];
      if (trigKey.startsWith('arousal_spike_')) {
        var threshold = parseInt(trigKey.split('_')[2], 10);
        if (arousal >= threshold) { fired = true; break; }
      } else if (events[trigKey]) {
        fired = true;
        break;
      }
    }
    if (!fired) continue;

    // ── Roll 1: d100 pressure gate ──
    // Combined fail count across ALL systems (masculinity + arousal + all effect resistances)
    // 1 fail = 1% chance. Simple, linear, never runs away.
    var arousalFails = parseInt(state._arousal_gate_fail_count || 0, 10);
    var mascFails = parseInt(state._masc_gate_fail_count || 0, 10);
    var resistFailMap = state._effect_resist_fail_count || {};
    var resistFails = 0;
    for (var _rk in resistFailMap) { resistFails += parseInt(resistFailMap[_rk] || 0, 10); }
    var failCount = arousalFails + mascFails + resistFails;
    // SUB stat adds baseline pressure — high SUB characters are naturally more susceptible
    var subStat = parseInt((state.stats || {}).SUB || 10, 10);
    var _arBand = _arousalDropBand(arousal);
    var arousalPressure = _ROLL1_AROUSAL_PRESSURE[_arBand] || 0;
    var pressureChance = Math.min(failCount + subStat + arousalPressure, _ROLL1_CAP);
    var d100 = Math.floor(Math.random() * 100) + 1;
    var pressurePass = d100 <= pressureChance;

    var r1Entry = eff + '_resist:ROLL1(d100=' + d100 + ' vs ' + pressureChance + '%'
      + ' fails=' + failCount + '+SUB' + subStat
      + (arousalPressure ? '+aro' + arousalPressure : '')
      + ' arousal=' + arousal
      + ' => ' + (pressurePass ? 'CHECK' : 'SKIP') + ')';
    (state.roll_log = state.roll_log || []).push(r1Entry);
    console.log('[RESIST] ' + r1Entry);

    if (!pressurePass) continue;

    // ── Roll 2: d20 + stat mods vs DC ──
    var resistMod = _snapshotEffectResistMod(state, eff);
    var storedDc = parseInt(state._effect_resist_dc[eff] || 10, 10);
    var appliedDc = storedDc;
    var _dcParts = [];
    var _counterStatName = _EFFECT_DC_COUNTER_STAT[eff];
    if (_counterStatName) {
      // B. Themed counter-stat (susceptibility stat per effect)
      var _counterMod = parseInt((state.stats || {})[_counterStatName] || 0, 10);
      // A. Snowball: the more eroded, the harder to resist further
      var _curResist = parseInt((state.effect_resistance || {})[eff] || 100, 10);
      var _snowball = Math.floor((100 - _curResist) / 10);
      // C. Streak cracking: +2 per completed 3-RESIST streak, resets on ERODE
      var _streakBonus = parseInt((state._effect_resist_streak_bonus || {})[eff] || 0, 10);
      appliedDc = Math.min(storedDc + _counterMod + _snowball + _streakBonus, _ROLL2_DC_CAP);
      _dcParts = [_counterStatName + '+' + _counterMod, 'snow+' + _snowball, 'streak+' + _streakBonus];
    }
    var d20 = Math.floor(Math.random() * 20) + 1;
    var total = d20 + resistMod;
    var resisted = total >= appliedDc;

    var r2Entry = eff + '_resist:ROLL2(d20=' + d20
      + (resistMod >= 0 ? '+' : '') + resistMod + '=' + total
      + ' vs DC=' + appliedDc
      + (_dcParts.length ? ' [' + _dcParts.join(' ') + ']' : '')
      + ' => ' + (resisted ? 'RESIST' : 'ERODE') + ')';
    (state.roll_log = state.roll_log || []).push(r2Entry);
    console.log('[RESIST] ' + r2Entry);

    // Streak tracking — RESIST consecutive counter bumps every 3, ERODE resets both
    if (_EFFECT_DC_COUNTER_STAT[eff]) {
      state._effect_resist_consecutive_resist = state._effect_resist_consecutive_resist || {};
      state._effect_resist_streak_bonus = state._effect_resist_streak_bonus || {};
      if (resisted) {
        var _cur = parseInt(state._effect_resist_consecutive_resist[eff] || 0, 10) + 1;
        state._effect_resist_consecutive_resist[eff] = _cur;
        if (_cur % 3 === 0) {
          state._effect_resist_streak_bonus[eff] = parseInt(state._effect_resist_streak_bonus[eff] || 0, 10) + 2;
        }
      } else {
        state._effect_resist_consecutive_resist[eff] = 0;
        state._effect_resist_streak_bonus[eff] = 0;
      }
    }

    if (resisted) {
      // Held — baseline DC still ticks up slightly (grind effect, separate from streak)
      state._effect_resist_dc[eff] = storedDc + 1;
      continue;
    }

    // ── Failed both rolls — apply arousal-scaled drop through boundary walk ──
    if (!state._effect_resist_fail_count || typeof state._effect_resist_fail_count !== 'object') state._effect_resist_fail_count = {};
    state._effect_resist_fail_count[eff] = (state._effect_resist_fail_count[eff] || 0) + 1;
    _applyEffectResistanceDelta(state, eff, dropAmount * _statGainFactor(state, eff));   // v7.12.0 stat-gain: erosion bite size
  }
}

