// Build resistance beat lines for injection into prompt
function _buildResistanceBeats(state) {
  var effects = state.active_effects || [];
  var resistance = state.effect_resistance || {};
  var lines = [];
  var _inMotherhood = _isMotherhoodMode(state);

  for (var i = 0; i < effects.length; i++) {
    var eff = effects[i];
    // v7.13.41 — compliant ships at EVERY band, including Untouched.
    //
    // Cody 2026-09-12: "compliant is they have to complie, they just 'fight' it based on
    // the stat band, so a more dom char will be diff [from] a more sub char."
    //
    // That settles a five-month-old misreading. v6.5.225 suppressed the whole table because
    // Untouched says "no automatic pull toward compliance", taken as contradicting the rule
    // that she carries out instructions. It does not: compliance is NOT in question under
    // this effect. She complies either way. The band describes how hard she fights on the
    // way there, so Untouched — preferences intact, agreement a conscious choice, nothing
    // pulling her — is the loudest fight, not an exemption. 7.13.40 restored ten bands;
    // this restores the eleventh.
    // Motherhood mode — breeder beats suppressed once motherhood begins (post-conception turn).
    // On conception turn itself, beats still present so the breeder climax narrates correctly.
    if (eff === 'breeder' && _inMotherhood) continue;
    // v7.7.41 — first-time arc selector for breeder. During the discovery arc
    // (breeder active, _breeder_first_climb_done false), pick from the
    // breeder_first_time table — same band/stat structure, but cognitive
    // framing is QUESTIONING (composure against an unfamiliar pull) rather
    // than KNOWN-THREAT (resisting a recognized force). After the first
    // creampie-orgasm flips the climb-done flag, this picker switches back
    // to the familiar `breeder` table.
    var beatsKey = eff;
    if (eff === 'breeder' && !state._breeder_first_climb_done) {
      beatsKey = 'breeder_first_time';
    }
    var beats = _EFFECT_RESISTANCE_BEATS[beatsKey];
    if (!beats) continue;

    var resist = resistance[eff];
    if (resist == null) continue;
    if (eff === 'breeder') resist = _breederEffectiveResistance(state);

    var band = _effectResistanceBand(resist);
    var bandBeats = beats[band];
    if (!bandBeats) continue;

    var label = _EFFECT_RESIST_BAND_LABELS[band] || 'Unknown';

    // v6.5.208: nest beats as <beat> children inside <resistance> instead of
    // emitting them as loose "DOM — text" lines, so the whole block is structured
    // engine-data and the model reads it as reference rather than prose.
    // v7.13.41 — the fight is this character's fight.
    //
    // Every one of the six stat beats used to ship for everyone, in a fixed order, so a
    // DOM 18 bully and a SUB 18 doormat received identical text about how they were
    // struggling. Cody: "based on the stat band, so a more dom char will be diff [from] a
    // more sub char." Now: the effect's own two governing stats (the axis the mechanic
    // pushes against, _EFFECT_RESIST_STATS) come first, then the stat this character is
    // furthest from average on. Three beats, and they are hers.
    var _charStats = state.stats || {};
    var _govern = _EFFECT_RESIST_STATS[eff] || [];
    var statOrder = [];
    for (var _g = 0; _g < _govern.length; _g++) {
      if (bandBeats[_govern[_g]] && statOrder.indexOf(_govern[_g]) === -1) statOrder.push(_govern[_g]);
    }
    var _byExtreme = ['DOM', 'SUB', 'WIS', 'CHA', 'CON', 'INT']
      .filter(function (st) { return bandBeats[st] && statOrder.indexOf(st) === -1; })
      .sort(function (a, b) {
        var av = Math.abs((parseInt(_charStats[a], 10) || 10) - 10);
        var bv = Math.abs((parseInt(_charStats[b], 10) || 10) - 10);
        return bv - av;
      });
    statOrder = statOrder.concat(_byExtreme).slice(0, 3);
    var hasBeats = statOrder.length > 0;

    // v7.13.39 — no effect="" attribute. The name is scrubbed out of this block before it
    // reaches the model (_stripEffectNames at the stateLines push), so the attribute always
    // arrived empty: <resistance effect="" level="Untouched" band="10">. An empty slot is
    // worse than no slot — with two effects active the model saw two blocks that looked
    // identical and had nothing to tell them apart. The level and band carry the meaning.
    if (!hasBeats) {
      lines.push('<resistance level="' + label + '" band="' + band + '"/>');
    } else {
      var resistOpen = '<resistance level="' + label + '" band="' + band + '">';
      var resistChildren = [];
      for (var s2 = 0; s2 < statOrder.length; s2++) {
        var stat = statOrder[s2];
        if (bandBeats[stat]) {
          resistChildren.push('  <beat attr="' + stat + '">' + bandBeats[stat] + '</beat>');
        }
      }
      lines.push(resistOpen + '\n' + resistChildren.join('\n') + '\n</resistance>');
    }
  }

  return lines;
}

// ──────────────────────────────────────────────────────────────────────────────
// BIMBO STAGE ADVANCE CHECK
// ──────────────────────────────────────────────────────────────────────────────

function _bimboAdvanceCheck(state) {
  // Only fires if bimbo effect is active and character is female
  const effects = state.active_effects || [];
  if (!effects.includes('bimbo')) return;
  const origin = state._sex_origin || 'male';
  if (origin !== 'female') return;

  const currentStage = parseInt((state.effect_stages || {}).bimbo || (state._effect_stages || {}).bimbo || 0, 10);
  if (currentStage >= 5) return; // already maxed

  // Combined fail count across ALL systems (session-scoped)
  const arousalFails = parseInt(state._arousal_gate_fail_count || 0, 10);
  const mascFails = parseInt(state._masc_gate_fail_count || 0, 10);
  const resistFailMap = state._effect_resist_fail_count || {};
  var resistFails = 0;
  for (var _rk in resistFailMap) { resistFails += parseInt(resistFailMap[_rk] || 0, 10); }
  const totalFails = arousalFails + mascFails + resistFails;

  // Roll 1 — d100 vs pressure bracket
  // 0-5 fails = 5%, 6-10 = 10%, 11-15 = 15%, etc.
  const bracket = totalFails <= 5 ? 5 : 5 + Math.ceil((totalFails - 5) / 5) * 5;
  const pressureChance = Math.min(bracket, 95); // cap at 95%
  const d100 = randInt(1, 100);
  const pressurePass = d100 <= pressureChance;

  const entry1 = 'bimbo_advance:ROLL1(d100=' + d100
    + ' vs ' + pressureChance + '%'
    + ' fails=' + totalFails
    + ' [arousal=' + arousalFails + ' masc=' + mascFails + ']'
    + ' => ' + (pressurePass ? 'TRIGGER' : 'NO_CHECK') + ')';
  (state.roll_log = state.roll_log || []).push(entry1);
  console.log('[BIMBO] ' + entry1);

  if (!pressurePass) return;

  // Roll 2 — d20 + INT mod + CHA mod vs DC (6 + total fails)
  const intVal = parseInt((state.stats || {}).INT || 10, 10);
  const chaVal = parseInt((state.stats || {}).CHA || 10, 10);
  const intMod = Math.floor((intVal - 10) / 2);
  const chaMod = Math.floor((chaVal - 10) / 2);
  const dc = 6 + totalFails;
  const d20 = randInt(1, 20);
  const total = d20 + intMod + chaMod;
  const resisted = total >= dc;

  const entry2 = 'bimbo_advance:ROLL2(d20=' + d20
    + ' INT_mod=' + (intMod >= 0 ? '+' : '') + intMod
    + ' CHA_mod=' + (chaMod >= 0 ? '+' : '') + chaMod
    + ' total=' + total + ' vs DC=' + dc
    + ' => ' + (resisted ? 'RESIST' : 'ADVANCE') + ')';
  (state.roll_log = state.roll_log || []).push(entry2);
  console.log('[BIMBO] ' + entry2);

  if (resisted) return;

  // Stage advances
  const newStage = currentStage + 1;
  if (!state._effect_stages) state._effect_stages = {};
  state._effect_stages.bimbo = newStage;
  if (!state.effect_stages) state.effect_stages = {};
  state.effect_stages.bimbo = newStage;
  if (!state.flavor) state.flavor = {};
  if (!state.flavor.bimbo) state.flavor.bimbo = {};
  state.flavor.bimbo.stage = newStage;

  // Apply INT penalty from new stage
  const intPenalty = -newStage;
  const baseInt = parseInt((state.stats || {}).INT || 10, 10);
  const newInt = Math.max(1, baseInt + intPenalty);

  const entry3 = 'bimbo_advance:STAGE=' + newStage
    + ' (INT penalty=' + intPenalty + ')';
  (state.roll_log = state.roll_log || []).push(entry3);
  (state._notes_log = state._notes_log || []).push(entry3);
  console.log('[BIMBO] ' + entry3);
}

