function _mod(state, key) {
  const raw = parseInt((state.stats || {})[key] || 10, 10);
  const perm = parseInt((state._perm_stat_mods || {})[key] || 0, 10);
  const temp = parseInt((state._temp_stat_mods || {})[key] || 0, 10);
  return _fragStatMod(raw + perm + temp);
}

