  // (character/user/scene/voice/state/transformation), markdown sections
  // for directives (Rules, Output). Replaces the legacy <engine-data>
  // wrapper. Routed via systemPrompt field so engine is sole source of
  // truth; ST sysMsg is filtered out by the extension (v2.0.0).

  // v7.13.5 — adopt the chosen (post-rename) name everywhere this header touches: the <character>
  // tag, the hard rules, the <state> block. _card_name keeps the ORIGINAL card name.
  if (state && state._chosen_name) name = state._chosen_name;
  var effSex   = currentSex(state, cardSex, rs);
  var _pn      = _charPronouns(effSex);   // v7.13.6 — sex-aware pronouns for the directives
  var charName = name || 'the character';
  // v7.0.1: prefer personaName (ctx.name1) over hardcoded 'Persona' literal
  var userName = (personaName && String(personaName).trim())
    || (personaState && personaState.name)
    || (persona && persona !== 'Persona' ? persona : null)
    || 'User';

  // ── Swipe recovery for deferred TX ──
  if (!state._deferred_transformation && state._deferred_tx_archive && !state._pill_descriptor_this_turn) {
    state._deferred_transformation = Object.assign({}, state._deferred_tx_archive);
    console.log('[XCW] Restored deferred transformation from swipe archive');
  }

