  var _txHasSurrogate = _txCandidate && (_txCandidate.effects || []).includes('surrogate');
  var _isTxTurn = !!(_txCandidate && (!_txPillRule.no_form_change || _txHasBimbo || _txHasSurrogate));

  // ── Character body attributes ──
  var resolved = state.resolved_body;
  var cardBodyFallback = state.card_body || {};
