    if (_bboRefresh.hips)  _charAttrs.splice(_povIdx, 0, 'hips="' + _xmlAttr(_bboRefresh.hips) + '"');
    if (_bboRefresh.waist) _charAttrs.splice(_povIdx, 0, 'waist="' + _xmlAttr(_bboRefresh.waist) + '"');
