  if (role === 'user') {
    var u = cleaned.length > 100 ? cleaned.substring(0, 97) + '...' : cleaned;
    return (u.length > 5 && !_isGarbled(u)) ? u : null;
  }

  // Assistant: dialogue + one action
  var sentences = cleaned.split(/(?<=[.!?])\s+/);
  sentences = sentences.filter(function(s) { return s.trim().length > 15 && !_isGarbled(s.trim()); });

  var parts = [];

  // First piece of dialogue
  for (var i = 0; i < sentences.length; i++) {
    var dm = sentences[i].match(/"([^"]{5,60})"/);
    if (dm) {
      parts.push('"' + dm[1].trim() + '"');
      break;
    }
  }

