    recentMessageCount: (state._pill_descriptor_this_turn || state._deferred_tx_archive || state._scene_jump_this_turn || state._antidote_revert_this_turn) ? 1 : 5,   // v7.12.1 — 3→5 (priority/TX turns still collapse to 1)
